from pathlib import Path

path = Path(__file__).with_name('apply_tiered_safety_fix.py')
text = path.read_text(encoding='utf-8')

header_old64 = ''
header_new64 = ''

footer_old64 = ''
footer_new64 = ''

lines = text.splitlines()
indices = [i for i, line in enumerate(lines) if line.startswith("replace_exact('src/HelpSys.Desktop/MainWindow.xaml'")]
if len(indices) < 2:
    raise RuntimeError(f'Expected at least two MainWindow.xaml patch calls, got {len(indices)}')
lines[indices[0]] = f"replace_exact('src/HelpSys.Desktop/MainWindow.xaml', '{header_old64}', '{header_new64}', 1)"
lines[indices[1]] = f"replace_exact('src/HelpSys.Desktop/MainWindow.xaml', '{footer_old64}', '{footer_new64}', 1)"
path.write_text('\n'.join(lines) + '\n', encoding='utf-8', newline='\n')
print('Both XAML patch anchors repaired')
